import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry sdpa_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 O_ptr
)
{
    .reg .pred %p<12>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<48>;
    .reg .f16 %h<6>;
    .reg .f32 %f<48>;

    .local .align 4 .b8 s_arr[1024]; // 256 * sizeof(float)

    // Load parameters
    ld.param.u64 %rdQ, [Q_ptr];
    ld.param.u64 %rdK, [K_ptr];
    ld.param.u64 %rdV, [V_ptr];
    ld.param.u64 %rdO, [O_ptr];

    // Compute linear thread id: tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mad.lo.u32 %r_tid, %r1, %r2, %r0;

    // Bounds check against total rows = B * H * S = 2 * 32 * 256 = 16384
    mov.u32 %rTotal, 16384;
    setp.ge.u32 %p0, %r_tid, %rTotal;
    @%p0 bra END;

    // Decompose tid into (b, h, i)
    // i = tid % 256
    rem.u32 %r_i, %r_tid, 256;
    // tmp = tid / 256
    div.u32 %r_tmp, %r_tid, 256;
    // h = tmp % 32
    rem.u32 %r_h, %r_tmp, 32;
    // b = tmp / 32
    div.u32 %r_b, %r_tmp, 32;

    // Compute row base index in elements: (((b*32 + h)*256 + i) * 1024)
    mad.lo.u32 %r_t1, %r_b, 32, %r_h;         // t1 = b*32 + h
    mad.lo.u32 %r_t2, %r_t1, 256, %r_i;       // t2 = (b*32 + h)*256 + i
    mul.lo.u32 %r_base_elem, %r_t2, 1024;     // base = t2 * 1024

    // Compute Q_row and O_row byte pointers
    mul.wide.u32 %rd_offQ, %r_base_elem, 2;
    add.s64 %rdQrow, %rdQ, %rd_offQ;

    mul.wide.u32 %rd_offO, %r_base_elem, 2;
    add.s64 %rdOrow, %rdO, %rd_offO;

    // Prepare local array base pointer
    cvta.local.u64 %rd_sbase, s_arr;

    // Initialize s_arr[j] = 0 for j in [0, 256)
    mov.b32 %f_zero, 0x00000000;
    mov.u32 %r_j, 0;
InitLoop:
    setp.ge.u32 %p1, %r_j, 256;
    @%p1 bra InitDone;
    mul.wide.u32 %rd_offS, %r_j, 4;
    add.s64 %rd_addr, %rd_sbase, %rd_offS;
    st.local.f32 [%rd_addr], %f_zero;
    add.u32 %r_j, %r_j, 1;
    bra InitLoop;
InitDone:

    // Accumulate scores s_j = sum_k Q[i,k] * K[j,k]
    mov.u32 %r_k, 0;
k_loop:
    setp.ge.u32 %p2, %r_k, 1024;
    @%p2 bra k_done;

    // Load qk = Q_row[k]
    mul.wide.u32 %rd_qoff, %r_k, 2;
    add.s64 %rd_qaddr, %rdQrow, %rd_qoff;
    ld.global.f16 %h0, [%rd_qaddr];
    cvt.f32.f16 %f_qk, %h0;

    // For each j in [0,256): s_j += qk * K[b,h,j,k]
    mov.u32 %r_j, 0;
j_in_k_loop:
    setp.ge.u32 %p3, %r_j, 256;
    @%p3 bra j_in_k_done;

    // Compute linear index for K[b,h,j,k]: (((b*32 + h)*256 + j) * 1024 + k)
    mad.lo.u32 %r_bhj, %r_t1, 256, %r_j;
    mad.lo.u32 %r_idx, %r_bhj, 1024, %r_k;
    mul.wide.u32 %rd_koff, %r_idx, 2;
    add.s64 %rd_kaddr, %rdK, %rd_koff;

    ld.global.f16 %h1, [%rd_kaddr];
    cvt.f32.f16 %f_k, %h1;

    // Load s_j
    mul.wide.u32 %rd_offS2, %r_j, 4;
    add.s64 %rd_saddr, %rd_sbase, %rd_offS2;
    ld.local.f32 %f_s, [%rd_saddr];

    // s_j += qk * k
    fma.rn.f32 %f_s, %f_qk, %f_k, %f_s;

    // Store back s_j
    st.local.f32 [%rd_saddr], %f_s;

    add.u32 %r_j, %r_j, 1;
    bra j_in_k_loop;
j_in_k_done:

    add.u32 %r_k, %r_k, 1;
    bra k_loop;
k_done:

    // Scale scores by 1/sqrt(d) = 1/32 = 0x3d000000
    mov.b32 %f_scale, 0x3d000000;
    mov.u32 %r_j, 0;
scale_loop:
    setp.ge.u32 %p4, %r_j, 256;
    @%p4 bra scale_done;
    mul.wide.u32 %rd_offS3, %r_j, 4;
    add.s64 %rd_saddr, %rd_sbase, %rd_offS3;
    ld.local.f32 %f_s, [%rd_saddr];
    mul.rn.f32 %f_s, %f_s, %f_scale;
    st.local.f32 [%rd_saddr], %f_s;
    add.u32 %r_j, %r_j, 1;
    bra scale_loop;
scale_done:

    // Find max over s_j
    mov.b32 %f_smax, 0xff7fffff; // -FLT_MAX
    mov.u32 %r_j, 0;
max_loop:
    setp.ge.u32 %p5, %r_j, 256;
    @%p5 bra max_done;
    mul.wide.u32 %rd_offS4, %r_j, 4;
    add.s64 %rd_saddr, %rd_sbase, %rd_offS4;
    ld.local.f32 %f_s, [%rd_saddr];
    max.f32 %f_smax, %f_smax, %f_s;
    add.u32 %r_j, %r_j, 1;
    bra max_loop;
max_done:

    // Compute exp(s_j - smax) and denom
    mov.b32 %f_denom, 0x00000000;
    mov.b32 %f_log2e, 0x3fb8aa3b; // log2(e)
    mov.u32 %r_j, 0;
exp_loop:
    setp.ge.u32 %p6, %r_j, 256;
    @%p6 bra exp_done;
    mul.wide.u32 %rd_offS5, %r_j, 4;
    add.s64 %rd_saddr, %rd_sbase, %rd_offS5;
    ld.local.f32 %f_s, [%rd_saddr];
    sub.rn.f32 %f_x, %f_s, %f_smax;
    mul.rn.f32 %f_y, %f_x, %f_log2e; // y = (s - smax) * log2(e)
    ex2.approx.f32 %f_e, %f_y;       // e = exp(s - smax)
    st.local.f32 [%rd_saddr], %f_e;  // store exp
    add.rn.f32 %f_denom, %f_denom, %f_e;
    add.u32 %r_j, %r_j, 1;
    bra exp_loop;
exp_done:

    // inv_denom
    rcp.approx.f32 %f_invden, %f_denom;

    // Normalize in place: w_j = exp / denom
    mov.u32 %r_j, 0;
norm_loop:
    setp.ge.u32 %p7, %r_j, 256;
    @%p7 bra norm_done;
    mul.wide.u32 %rd_offS6, %r_j, 4;
    add.s64 %rd_saddr, %rd_sbase, %rd_offS6;
    ld.local.f32 %f_e, [%rd_saddr];
    mul.rn.f32 %f_w, %f_e, %f_invden;
    st.local.f32 [%rd_saddr], %f_w;
    add.u32 %r_j, %r_j, 1;
    bra norm_loop;
norm_done:

    // For each e in [0,1024): out[e] = sum_j w_j * V[b,h,j,e]
    mov.u32 %r_e, 0;
e_loop:
    setp.ge.u32 %p8, %r_e, 1024;
    @%p8 bra e_done;

    mov.b32 %f_sum, 0x00000000;

    mov.u32 %r_j, 0;
vj_loop:
    setp.ge.u32 %p9, %r_j, 256;
    @%p9 bra vj_done;

    // w_j
    mul.wide.u32 %rd_offS7, %r_j, 4;
    add.s64 %rd_saddr, %rd_sbase, %rd_offS7;
    ld.local.f32 %f_wj, [%rd_saddr];

    // V index: (((b*32 + h)*256 + j)*1024 + e)
    mad.lo.u32 %r_bhj2, %r_t1, 256, %r_j;
    mad.lo.u32 %r_vidx, %r_bhj2, 1024, %r_e;
    mul.wide.u32 %rd_voff, %r_vidx, 2;
    add.s64 %rd_vaddr, %rdV, %rd_voff;

    ld.global.f16 %h2, [%rd_vaddr];
    cvt.f32.f16 %f_v, %h2;

    fma.rn.f32 %f_sum, %f_wj, %f_v, %f_sum;

    add.u32 %r_j, %r_j, 1;
    bra vj_loop;
vj_done:

    // Store output as f16
    cvt.rn.f16.f32 %h3, %f_sum;
    mul.wide.u32 %rd_ooff, %r_e, 2;
    add.s64 %rd_oaddr, %rdOrow, %rd_ooff;
    st.global.f16 [%rd_oaddr], %h3;

    add.u32 %r_e, %r_e, 1;
    bra e_loop;
e_done:

END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sdpa_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Allocate output tensor
        out = torch.empty_like(Q)

        # Compute grid/block
        B, H, S, E = Q.shape
        n_rows = B * H * S
        block_x = 128
        grid_x = (n_rows + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "sdpa_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

