class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Allocate output tensor
        out = torch.empty_like(Q)

        # Compute grid/block
        B, H, S, E = Q.shape
        n_rows = B * H * S
        block_x = 128
        grid_x = (n_rows + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "sdpa_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[Q, K, V, out],
